package org.eclipse.kura.core.keystore;

import java.util.HashMap;
import java.util.Map;

import org.junit.Test;

public class KeystoreInitializationTest extends AbstractFilesystemKeystoreServiceTest {

    private static final String OTHER_KEYSTORE_NAME = "other.store";

    @Test
    public void createsEmptyKeystoreForNewPath() throws Exception {
        whenKeystoreServiceIsActivated();

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, PASSWORD);
        thenDirectoryContainsOnly(KEYSTORE_NAME);
    }

    @Test
    public void keepsCorruptedKeystoreAtActivation() throws Exception {
        givenCorruptedFile(KEYSTORE_NAME);

        whenKeystoreServiceIsActivated();

        thenNoExceptionIsThrown();
        thenFileIsCorrupted(KEYSTORE_NAME);
        thenDirectoryContainsOnly(KEYSTORE_NAME);
    }

    @Test
    public void deletesStaleTempFileAtActivation() throws Exception {
        givenKeystoreWithCertificate("current");
        givenStaleTempFile(KEYSTORE_NAME + ".tmp");

        whenKeystoreServiceIsActivated();

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(KEYSTORE_NAME, PASSWORD, "current");
        thenDirectoryContainsOnly(KEYSTORE_NAME);
    }

    @Test
    public void deletesStaleTempFileWhenPathChanges() throws Exception {
        givenActivatedKeystoreService();
        givenOtherKeystoreWithCertificate("other");
        givenStaleTempFile(OTHER_KEYSTORE_NAME + ".tmp");

        whenKeystorePathIsChangedTo(OTHER_KEYSTORE_NAME);

        thenNoExceptionIsThrown();
        thenKeystoreFileContainsOnly(OTHER_KEYSTORE_NAME, PASSWORD, "other");
        thenDirectoryContainsOnly(KEYSTORE_NAME, OTHER_KEYSTORE_NAME);
    }

    private void givenOtherKeystoreWithCertificate(final String alias) throws Exception {
        writeKeystoreFile(OTHER_KEYSTORE_NAME, alias);
    }

    private void givenStaleTempFile(final String name) throws Exception {
        writeKeystoreFile(name, "stale");
    }

    private void whenKeystorePathIsChangedTo(final String name) {
        final Map<String, Object> updatedProperties = new HashMap<>(this.properties);
        updatedProperties.put(FilesystemKeystoreServiceOptions.KEY_KEYSTORE_PATH, keystoreFile(name).getPath());
        try {
            this.keystoreService.updated(updatedProperties);
        } catch (Exception e) {
            this.exception = e;
        }
    }
}
